    "G09G": {
      "code": "G09G",
      "level": 0,
      "parent": null,
      "ja": "",
      "en": "",
      "count": 0,
      "ipcCode": "",
      "fTerm": "ARRANGEMENTS OR CIRCUITS FOR CONTROL OF INDICATING DEVICES USING STATIC MEANS TO PRESENT VARIABLE INFORMATION (arrangements for transferring data between digital computers and displays <b>G06F 3/14</b>;  static indicating arrangements comprising an association of a number of separate sources or light control cells <b>G09F 9/00</b>;  static indicating arrangements comprising integral associations of a number of light sources <b>H01J</b>, <b>H01K</b>, <b>H05B 33/12</b>, <b>H10H</b>;  scanning, transmission or reproduction of documents or the like, e.g. facsimile transmission, details thereof <b>H04N 1/00</b>)<b>[3,4,5]</b><br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>This subclass <u>covers</u> indicator consoles, i.e. arrangements or circuits for processing control signals to achieve the display, e.g. for the calling up, reception, storage, regeneration, coding, decoding, addressing of control signals.<b>[3]</b></li><li>This subclass <u>does not cover</u> the structural details of the indicating devices, such as panels or tubes <u>per se</u>, or assemblies of individual light sources, which are covered by the relevant subclasses, e.g.  <b>G02F</b>, <b>G09F</b>, <b>H01J</b>, <b>H01K</b>, <b>H05B</b>, <b>H10H</b>, <b>H10K</b>.</li><li>Contrary to subclass <b>H04N</b>, in which are classified display devices capable of representing continuous brightness value scales, this subclass is limited to devices using only a discrete number of brightness values, e.g. visible/non-visible.</li><li>The visual effect may be produced by a luminescent screen scanned by an electron beam, directly by controlled light sources, by projection of light, from controlled light sources onto characters, symbols, or elements thereof drawn on a support, or by electric, magnetic, or acoustic control of the parameters of light rays from an independent source.</li></ul>",
      "childFlag": 0,
      "sourceFile": "fi_G.txt",
      "kind": "fi"
    },
